func memoIDSetFromRefs(memos []deleteUserMemoRef) map[int32]struct{} {
	idSet := make(map[int32]struct{}, len(memos))
	for _, memo := range memos {
		idSet[memo.ID] = struct{}{}
	}
	return idSet
